/// Samples a region and age in days from the 108 demographic weights.
pub fn sample_age_and_region_from_distribution(
    rng: &mut impl rand::Rng,
) -> (crate::simulation::population::Region, i32) {
    use crate::simulation::population::Region;

    // Build cumulative probability distribution
    let mut cumulative_probs = Vec::new();
    let mut running_total = 0.0;

    // Define regions and age bands in days relative to birth.
    let regions = [
        Region::Asia,
        Region::Africa,
        Region::Europe,
        Region::NorthAmerica,
        Region::SouthAmerica,
        Region::Oceania,
    ];

    let age_bands = [
        (-40000, -36000),
        (-36000, -32000),
        (-32000, -28000),
        (-28000, -24000),
        (-24000, -20000),
        (-20000, -16000),
        (-16000, -12000),
        (-12000, -8000),
        (-8000, -4000),
        (-4000, 0),
        (0, 4000),
        (4000, 8000),
        (8000, 12000),
        (12000, 16000),
        (16000, 20000),
        (20000, 24000),
        (24000, 28000),
        (28000, 32000),
    ];

    // Build distribution
    for region in &regions {
        let region_name = match region {
            Region::Asia => "asia",
            Region::Africa => "africa",
            Region::Europe => "europe",
            Region::NorthAmerica => "north_america",
            Region::SouthAmerica => "south_america",
            Region::Oceania => "oceania",
            Region::Home => "north_america", // Default fallback
        };

        for (age_min, age_max) in &age_bands {
            let param_name = if *age_min < 0 && *age_max <= 0 {
                format!(
                    "demo_{}_age_neg{}_neg{}",
                    region_name,
                    (*age_min as i32).abs(),
                    (*age_max as i32).abs()
                )
            } else if *age_min < 0 && *age_max > 0 {
                format!("demo_{}_age_neg{}_0", region_name, (*age_min as i32).abs())
            } else {
                format!("demo_{}_age_{}_{}", region_name, age_min, age_max)
            };
            let prob = get_global_param(&param_name).unwrap_or(0.0);
            running_total += prob;
            cumulative_probs.push((running_total, *region, *age_min, *age_max));
        }
    }

    // Sample from distribution
    let random_value = rng.gen::<f64>() * running_total;

    for (cumulative_prob, region, age_min, age_max) in cumulative_probs {
        if random_value <= cumulative_prob {
            // Sample uniformly within the age band
            let age = rng.gen_range(age_min..age_max);
            return (region, age);
        }
    }

    // Fallback (should rarely be reached)
    (Region::Asia, 0)
}

/// Returns the dormant pairwise drug-level entries for debugging or documentation.
#[allow(dead_code)]
pub fn get_all_active_interactions() -> Vec<(String, String, f64)> {
    let mut interactions = Vec::new();

    // Keep this list synchronized with the compatibility entries in PARAMETERS.
    let known_interactions = vec![
        ("levofloxacin", "rifampicin", 0.7),
        ("moxifloxacin", "rifampicin", 0.8),
        ("clarithromycin", "rifampicin", 0.6),
        ("azithromycin", "rifampicin", 0.8),
        ("ciprofloxacin", "amoxicillin_clavulanate", 0.85),
        ("levofloxacin", "amoxicillin_clavulanate", 0.9),
        ("ciprofloxacin", "erythromycin", 0.85),
        ("levofloxacin", "azithromycin", 0.9),
    ];

    for (drug1, drug2, multiplier) in known_interactions {
        interactions.push((drug1.to_string(), drug2.to_string(), multiplier));
    }

    interactions
}

/// Broad drug-class label used by generated parameter documentation.
///
/// This reporting grouping is not used to determine mechanism applicability or resistance.
pub fn get_drug_class(drug: &str) -> Option<&'static str> {
    match drug {
        "penicillin_g"
        | "ampicillin"
        | "amoxicillin"
        | "piperacillin"
        | "ticarcillin"
        | "flucloxacillin"
        | "amoxicillin_clavulanate"
        | "piperacillin_tazobactam"
        | "ampicillin_sulbactam"
        | "ticarcillin_clavulanate" => Some("penicillins"),
        "cephalexin" | "cefazolin" | "cefuroxime" => Some("cephalosporins_1_2"),
        "ceftriaxone"
        | "ceftazidime"
        | "cefixime"
        | "cefepime"
        | "ceftaroline"
        | "cefiderocol"
        | "ceftazidime_avibactam"
        | "ceftolozane_tazobactam"
        | "aztreonam"
        | "aztreonam_avibactam" => Some("cephalosporins_3_4"),
        "meropenem" | "imipenem_c" | "ertapenem" | "meropenem_vaborbactam" => Some("carbapenems"),
        "erythromycin" | "azithromycin" | "clarithromycin" | "clindamycin" => Some("macrolides"),
        "gentamicin" | "tobramycin" | "amikacin" => Some("aminoglycosides"),
        "ciprofloxacin" | "levofloxacin" | "moxifloxacin" | "ofloxacin" | "nalidixic_acid" => {
            Some("fluoroquinolones")
        }
        "tetracycline" | "doxycycline" | "minocycline" | "tigecycline" => Some("tetracyclines"),
        "vancomycin" => Some("glycopeptides"),
        "teicoplanin" | "dalbavancin" => Some("lipoglycopeptides"),
        "linezolid" | "tedizolid" => Some("oxazolidinones"),
        "trim_sulf" | "sulfanilamide" => Some("folate_antagonists"),
        "colistin" => Some("polymyxins"),
        "metronidazole" => Some("nitroimidazoles"),
        _ => None,
    }
}
// ============================================================================
// PATHWAY SENSITIVITY CONTROLS
//
// These neutral run-level multipliers support diagnostic ablations and global
// sensitivity analysis without rewriting organism-specific parameter tables. They
// are not a predetermined calibration scheme; any later calibration use should be
// supported by target relevance and identifiability checks.
//
// Infection de novo emergence  (run_pathway_infection_de_novo_multiplier)
//   Scales bacterium-mechanism emergence probabilities during active infection.
//
// Resistance reversion rate  (run_pathway_reversion_rate_multiplier)
//   Scales eligible unselected mechanism-loss probabilities.
//
// Horizontal gene transfer  (run_pathway_hgt_multiplier)
//   Scales eligible within-person HGT probabilities.
//
// Microbiome reservoir seeding  (run_pathway_microbiome_acquisition_multiplier)
//   Scales resistant-profile sampling during new microbiome acquisition. Community
//   acquisitions are also gated by the bacterium-specific dilution factor.
// ============================================================================
